[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>CommerceForge Dev Docs</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap" rel="stylesheet">
<style>
  :root {
    --bg-primary: #0d1117;
    --bg-secondary: #161b22;
    --bg-tertiary: #21262d;
    --bg-card: #161b22;
    --border: rgba(48, 54, 61, 0.8);
    --border-hover: rgba(71, 95, 145, 0.6);
    --text-primary: #e6edf3;
    --text-secondary: #8b949e;
    --text-muted: #6e7681;
    --accent: #475F91;
    --accent-bright: #58a6ff;
    --accent-green: #3fb950;
    --accent-cyan: #79c0ff;
    --font-mono: 'JetBrains Mono', 'Fira Code', monospace;
    --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
    --radius-sm: 6px;
    --radius-md: 10px;
    --radius-lg: 16px;
    --shadow-card: 0 1px 3px rgba(0,0,0,0.4), 0 0 0 1px rgba(48,54,61,0.8);
    --transition: 200ms ease;
  }

  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

  html { scroll-behavior: smooth; }

  body {
    font-family: var(--font-sans);
    background: var(--bg-primary);
    color: var(--text-primary);
    line-height: 1.6;
    min-height: 100vh;
    font-size: 16px;
    -webkit-font-smoothing: antialiased;
  }

  a { color: var(--accent-bright); text-decoration: none; }
  a:hover { text-decoration: underline; }
  a:focus-visible { outline: 2px solid var(--accent-bright); outline-offset: 2px; border-radius: 3px; }

  /* ── NAV ── */
  .nav {
    position: sticky;
    top: 0;
    z-index: 100;
    background: rgba(13,17,23,0.92);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border-bottom: 1px solid var(--border);
  }
  .nav-inner {
    max-width: 1280px;
    margin: 0 auto;
    padding: 0 24px;
    height: 56px;
    display: flex;
    align-items: center;
    gap: 32px;
  }
  .nav-logo {
    font-weight: 700;
    font-size: 15px;
    color: var(--text-primary);
    text-decoration: none;
    white-space: nowrap;
    display: flex;
    align-items: center;
    gap: 8px;
  }
  .nav-logo:hover { text-decoration: none; }
  .nav-logo-icon {
    width: 28px; height: 28px;
    background: linear-gradient(135deg, var(--accent) 0%, var(--accent-bright) 100%);
    border-radius: 6px;
    display: flex; align-items: center; justify-content: center;
    flex-shrink: 0;
  }
  .nav-links {
    display: flex;
    gap: 4px;
    flex: 1;
  }
  .nav-links a {
    color: var(--text-secondary);
    font-size: 14px;
    font-weight: 500;
    padding: 6px 12px;
    border-radius: var(--radius-sm);
    transition: color var(--transition), background var(--transition);
    text-decoration: none;
  }
  .nav-links a:hover { color: var(--text-primary); background: var(--bg-tertiary); text-decoration: none; }
  .nav-links a.active { color: var(--text-primary); }
  .nav-actions {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-left: auto;
  }
  .nav-search {
    display: flex;
    align-items: center;
    gap: 8px;
    background: var(--bg-tertiary);
    border: 1px solid var(--border);
    border-radius: var(--radius-sm);
    padding: 6px 12px;
    font-size: 13px;
    color: var(--text-muted);
    cursor: pointer;
    transition: border-color var(--transition);
    white-space: nowrap;
  }
  .nav-search:hover { border-color: var(--accent); }
  .nav-btn {
    font-size: 14px;
    font-weight: 500;
    color: var(--text-secondary);
    background: none;
    border: 1px solid var(--border);
    padding: 6px 14px;
    border-radius: var(--radius-sm);
    cursor: pointer;
    transition: color var(--transition), border-color var(--transition);
    font-family: var(--font-sans);
  }
  .nav-btn:hover { color: var(--text-primary); border-color: var(--accent); }

  /* ── HERO ── */
  .hero {
    padding: 80px 24px 64px;
    max-width: 1280px;
    margin: 0 auto;
    position: relative;
  }
  .hero::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 400px;
    background: radial-gradient(ellipse 60% 40% at 50% -10%, rgba(71,95,145,0.18) 0%, transparent 70%);
    pointer-events: none;
  }
  .hero-badge {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    font-size: 12px;
    font-weight: 500;
    color: var(--accent-green);
    background: rgba(63,185,80,0.12);
    border: 1px solid rgba(63,185,80,0.25);
    padding: 4px 10px;
    border-radius: 20px;
    margin-bottom: 20px;
    letter-spacing: 0.03em;
    text-transform: uppercase;
  }
  .hero-badge-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--accent-green); animation: pulse 2s infinite; }
  @keyframes pulse { 0%,100%{opacity:1}50%{opacity:.5} }
  .hero h1 {
    font-size: clamp(32px, 5vw, 56px);
    font-weight: 700;
    line-height: 1.15;
    letter-spacing: -0.02em;
    margin-bottom: 20px;
    background: linear-gradient(135deg, #e6edf3 0%, #8b949e 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    max-width: 700px;
  }
  .hero p {
    font-size: 17px;
    color: var(--text-secondary);
    max-width: 620px;
    line-height: 1.7;
    margin-bottom: 36px;
  }
  .hero-ctas {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
  }
  .btn {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 10px 20px;
    border-radius: var(--radius-sm);
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    transition: all var(--transition);
    text-decoration: none;
    border: none;
    font-family: var(--font-sans);
    white-space: nowrap;
  }
  .btn:focus-visible { outline: 2px solid var(--accent-bright); outline-offset: 2px; }
  .btn:hover { text-decoration: none; }
  .btn-primary {
    background: var(--accent);
    color: #fff;
  }
  .btn-primary:hover { background: #5a74aa; transform: translateY(-1px); box-shadow: 0 4px 16px rgba(71,95,145,0.35); }
  .btn-secondary {
    background: var(--bg-tertiary);
    color: var(--text-primary);
    border: 1px solid var(--border);
  }
  .btn-secondary:hover { background: var(--bg-card); border-color: var(--accent); transform: translateY(-1px); }
  .btn-ghost {
    background: none;
    color: var(--accent-bright);
    border: 1px solid rgba(88,166,255,0.3);
  }
  .btn-ghost:hover { background: rgba(88,166,255,0.08); border-color: var(--accent-bright); }

  /* ── SECTION ── */
  .section { padding: 64px 24px; }
  .section-inner { max-width: 1280px; margin: 0 auto; }
  .section-label {
    font-size: 12px;
    font-weight: 600;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--accent-bright);
    margin-bottom: 8px;
  }
  .section-title {
    font-size: clamp(22px, 3vw, 32px);
    font-weight: 700;
    letter-spacing: -0.01em;
    color: var(--text-primary);
    margin-bottom: 10px;
  }
  .section-subtitle {
    font-size: 16px;
    color: var(--text-secondary);
    max-width: 560px;
    line-height: 1.65;
    margin-bottom: 48px;
  }

  /* ── PRODUCT CARDS ── */
  .product-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 20px;
    margin-bottom: 0;
  }
  .product-card {
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: var(--radius-lg);
    padding: 32px;
    transition: border-color var(--transition), transform var(--transition), box-shadow var(--transition);
    position: relative;
    overflow: hidden;
    display: flex;
    flex-direction: column;
  }
  .product-card::before {
    content: '';
    position: absolute;
    inset: 0;
    background: linear-gradient(135deg, rgba(71,95,145,0.05) 0%, transparent 60%);
    pointer-events: none;
  }
  .product-card:hover {
    border-color: var(--border-hover);
    transform: translateY(-2px);
    box-shadow: 0 8px 32px rgba(0,0,0,0.3);
  }
  .product-card.apps::before { background: linear-gradient(135deg, rgba(88,166,255,0.07) 0%, transparent 60%); }
  .product-card.storefronts::before { background: linear-gradient(135deg, rgba(63,185,80,0.07) 0%, transparent 60%); }
  .product-card.agents::before { background: linear-gradient(135deg, rgba(121,192,255,0.07) 0%, transparent 60%); }
  .product-card-icon {
    width: 44px; height: 44px;
    border-radius: 10px;
    display: flex; align-items: center; justify-content: center;
    margin-bottom: 20px;
    flex-shrink: 0;
  }
  .icon-apps { background: rgba(88,166,255,0.12); }
  .icon-storefronts { background: rgba(63,185,80,0.12); }
  .icon-agents { background: rgba(121,192,255,0.12); }
  .product-card h3 {
    font-size: 18px;
    font-weight: 700;
    color: var(--text-primary);
    margin-bottom: 10px;
  }
  .product-card p {
    font-size: 14px;
    color: var(--text-secondary);
    line-height: 1.65;
    flex: 1;
    margin-bottom: 24px;
  }
  .card-link {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    font-size: 14px;
    font-weight: 600;
    color: var(--accent-bright);
    text-decoration: none;
    transition: gap var(--transition);
    margin-top: auto;
  }
  .card-link:hover { gap: 10px; text-decoration: none; }
  .card-link-green { color: var(--accent-green); }
  .card-link-cyan { color: var(--accent-cyan); }

  /* ── CLI SECTION ── */
  .cli-section {
    background: var(--bg-secondary);
    border-top: 1px solid var(--border);
    border-bottom: 1px solid var(--border);
  }
  .cli-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 48px;
    align-items: start;
  }
  .cli-left {}
  .cli-accordions {
    display: flex;
    flex-direction: column;
    gap: 0;
    border: 1px solid var(--border);
    border-radius: var(--radius-md);
    overflow: hidden;
  }
  .accordion-item {
    border-bottom: 1px solid var(--border);
  }
  .accordion-item:last-child { border-bottom: none; }
  .accordion-trigger {
    width: 100%;
    background: var(--bg-tertiary);
    border: none;
    padding: 16px 20px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    cursor: pointer;
    font-family: var(--font-sans);
    font-size: 14px;
    font-weight: 600;
    color: var(--text-primary);
    transition: background var(--transition);
    text-align: left;
  }
  .accordion-trigger:hover { background: var(--bg-card); }
  .accordion-trigger[aria-expanded="true"] { background: var(--bg-primary); color: var(--accent-bright); }
  .accordion-trigger:focus-visible { outline: 2px solid var(--accent-bright); outline-offset: -2px; }
  .accordion-chevron {
    transition: transform 250ms ease;
    flex-shrink: 0;
  }
  .accordion-trigger[aria-expanded="true"] .accordion-chevron { transform: rotate(180deg); }
  .accordion-content {
    display: none;
    background: var(--bg-primary);
  }
  .accordion-content.open { display: block; }
  .accordion-steps {
    padding: 20px;
    display: flex;
    flex-direction: column;
    gap: 12px;
  }
  .step {
    display: flex;
    gap: 14px;
    align-items: flex-start;
  }
  .step-num {
    width: 24px; height: 24px;
    border-radius: 50%;
    background: rgba(71,95,145,0.2);
    border: 1px solid rgba(71,95,145,0.4);
    display: flex; align-items: center; justify-content: center;
    font-size: 11px;
    font-weight: 700;
    color: var(--accent-bright);
    flex-shrink: 0;
    margin-top: 1px;
  }
  .step p { font-size: 13px; color: var(--text-secondary); line-height: 1.5; }

  .cli-right {}
  .code-block {
    background: #0d1117;
    border: 1px solid var(--border);
    border-radius: var(--radius-md);
    overflow: hidden;
  }
  .code-tabs {
    display: flex;
    border-bottom: 1px solid var(--border);
    padding: 0 16px;
    background: var(--bg-tertiary);
  }
  .code-tab {
    background: none;
    border: none;
    padding: 10px 14px;
    font-size: 13px;
    font-weight: 500;
    color: var(--text-muted);
    cursor: pointer;
    position: relative;
    font-family: var(--font-sans);
    transition: color var(--transition);
    border-bottom: 2px solid transparent;
    margin-bottom: -1px;
  }
  .code-tab:hover { color: var(--text-primary); }
  .code-tab.active {
    color: var(--accent-bright);
    border-bottom-color: var(--accent-bright);
  }
  .code-tab:focus-visible { outline: 2px solid var(--accent-bright); outline-offset: -2px; }
  .code-panel { display: none; }
  .code-panel.active { display: block; }
  .code-block-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 10px 16px;
    border-bottom: 1px solid var(--border);
    background: var(--bg-tertiary);
  }
  .code-block-label {
    font-size: 12px;
    color: var(--text-muted);
    font-family: var(--font-mono);
  }
  .copy-btn {
    background: none;
    border: 1px solid var(--border);
    padding: 3px 10px;
    border-radius: 4px;
    font-size: 12px;
    color: var(--text-muted);
    cursor: pointer;
    font-family: var(--font-sans);
    transition: all var(--transition);
  }
  .copy-btn:hover { color: var(--text-primary); border-color: var(--accent); }
  .code-body {
    padding: 20px 24px;
    font-family: var(--font-mono);
    font-size: 13px;
    line-height: 1.7;
    color: #e6edf3;
    overflow-x: auto;
  }
  .code-comment { color: #8b949e; }
  .code-cmd { color: var(--accent-green); }
  .code-pkg { color: var(--accent-cyan); }
  .code-flag { color: #ffa657; }
  .code-block-meta {
    padding: 16px;
    background: var(--bg-tertiary);
    border-top: 1px solid var(--border);
    font-size: 12px;
    color: var(--text-muted);
  }
  .code-block-meta strong { color: var(--text-secondary); }

  /* ── LAUNCH CTA ── */
  .launch-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
  }
  .launch-card {
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: var(--radius-lg);
    padding: 32px;
    transition: border-color var(--transition), box-shadow var(--transition);
  }
  .launch-card:hover { border-color: var(--border-hover); box-shadow: 0 4px 20px rgba(0,0,0,0.25); }
  .launch-card h3 { font-size: 18px; font-weight: 700; margin-bottom: 10px; }
  .launch-card p { font-size: 14px; color: var(--text-secondary); line-height: 1.65; margin-bottom: 20px; }

  /* ── COMMUNITY ── */
  .community-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
  }
  .community-card {
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: var(--radius-md);
    padding: 24px;
    transition: border-color var(--transition), transform var(--transition);
    text-decoration: none;
    display: block;
  }
  .community-card:hover { border-color: var(--border-hover); transform: translateY(-2px); text-decoration: none; }
  .community-card:focus-visible { outline: 2px solid var(--accent-bright); outline-offset: 2px; border-radius: var(--radius-md); }
  .community-icon {
    width: 36px; height: 36px;
    border-radius: 8px;
    display: flex; align-items: center; justify-content: center;
    background: rgba(71,95,145,0.15);
    margin-bottom: 14px;
  }
  .community-card h4 { font-size: 14px; font-weight: 700; color: var(--text-primary); margin-bottom: 6px; }
  .community-card p { font-size: 13px; color: var(--text-secondary); line-height: 1.5; }

  /* ── FOOTER ── */
  footer {
    border-top: 1px solid var(--border);
    padding: 48px 24px;
    background: var(--bg-secondary);
  }
  .footer-inner {
    max-width: 1280px;
    margin: 0 auto;
    display: grid;
    grid-template-columns: 1.5fr 1fr 1fr 1fr;
    gap: 40px;
  }
  .footer-brand p { font-size: 13px; color: var(--text-secondary); margin-top: 10px; line-height: 1.6; max-width: 220px; }
  .footer-col h5 {
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: var(--text-muted);
    margin-bottom: 12px;
  }
  .footer-col ul { list-style: none; display: flex; flex-direction: column; gap: 8px; }
  .footer-col a { font-size: 13px; color: var(--text-secondary); transition: color var(--transition); }
  .footer-col a:hover { color: var(--text-primary); text-decoration: none; }
  .footer-bottom {
    max-width: 1280px;
    margin: 24px auto 0;
    padding-top: 20px;
    border-top: 1px solid var(--border);
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 12px;
  }
  .footer-bottom p { font-size: 12px; color: var(--text-muted); }

  /* ── DIVIDER ── */
  .divider { height: 1px; background: var(--border); margin: 0; }

  /* ── RESPONSIVE ── */
  @media (max-width: 1024px) {
    .product-grid { grid-template-columns: repeat(2, 1fr); }
    .community-grid { grid-template-columns: repeat(2, 1fr); }
    .footer-inner { grid-template-columns: 1fr 1fr; gap: 32px; }
    .cli-grid { grid-template-columns: 1fr; gap: 32px; }
  }
  @media (max-width: 768px) {
    .nav-links { display: none; }
    .hero { padding: 48px 16px 40px; }
    .section { padding: 48px 16px; }
    .product-grid { grid-template-columns: 1fr; }
    .launch-grid { grid-template-columns: 1fr; }
    .community-grid { grid-template-columns: 1fr 1fr; }
    .footer-inner { grid-template-columns: 1fr; }
    .hero-ctas { flex-direction: column; }
    .btn { width: 100%; justify-content: center; }
    footer { padding: 36px 16px; }
  }
  @media (max-width: 480px) {
    .community-grid { grid-template-columns: 1fr; }
  }
  @media (prefers-reduced-motion: reduce) {
    *, *::before, *::after { transition: none !important; animation: none !important; }
  }
</style>
</head>
<body>

<!-- NAV -->
<nav class="nav" role="navigation" aria-label="Main navigation">
  <div class="nav-inner">
    <a href="index.html" class="nav-logo" aria-label="CommerceForge Dev Docs home">
      <div class="nav-logo-icon" aria-hidden="true">
        <svg width="16" height="16" viewBox="0 0 16 16" fill="none"><path d="M2 4h12M2 8h8M2 12h10" stroke="#fff" stroke-width="2" stroke-linecap="round"/></svg>
      </div>
      CommerceForge
    </a>
    <div class="nav-links">
      <a href="apps-build.html" class="active">Apps</a>
      <a href="storefronts.html">Storefronts</a>
      <a href="agents.html">Agents</a>
      <a href="#" aria-label="References documentation">References</a>
      <a href="support.html">Help</a>
    </div>
    <div class="nav-actions">
      <div class="nav-search" role="search" aria-label="Search documentation">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/></svg>
        Ask assistant
        <kbd style="font-size:11px;background:rgba(255,255,255,0.07);padding:1px 5px;border-radius:3px;color:var(--text-muted)">/</kbd>
      </div>
      <button class="nav-btn" type="button">Log in</button>
    </div>
  </div>
</nav>

<!-- HERO -->
<main id="main-content">
<section class="hero" aria-labelledby="hero-heading">
  <div class="hero-badge">
    <span class="hero-badge-dot" aria-hidden="true"></span>
    CLI 3.0 Now Available
  </div>
  <h1 id="hero-heading">CommerceForge<br>Dev Docs</h1>
  <p>Learn how to build an app, or customize your storefront. Whether you're just getting started, deep in the development process, or ready to distribute and monetize your work, CommerceForge's docs, dev tools and frameworks make building easy and efficient.</p>
  <div class="hero-ctas">
    <a href="apps-build.html" class="btn btn-primary">Build your first app <span aria-hidden="true">→</span></a>
    <a href="storefronts.html" class="btn btn-secondary">Build a storefront <span aria-hidden="true">→</span></a>
    <a href="agents.html" class="btn btn-ghost">Build agents with UCP <span aria-hidden="true">→</span></a>
  </div>
</section>

<!-- PRODUCT CARDS -->
<section class="section" aria-labelledby="products-heading">
  <div class="section-inner">
    <span class="section-label">What will you build?</span>
    <h2 class="section-title" id="products-heading">Three ways to build on CommerceForge</h2>
    <p class="section-subtitle">Choose your path and start building commerce experiences that scale.</p>
    <div class="product-grid">
      <!-- Apps -->
