<script>
// Accordion — one open at a time
document.querySelectorAll('.accordion-trigger').forEach(trigger => {
  trigger.addEventListener('click', () => {
    const isOpen = trigger.getAttribute('aria-expanded') === 'true';
    // Close all
    document.querySelectorAll('.accordion-trigger').forEach(t => {
      t.setAttribute('aria-expanded', 'false');
      document.getElementById(t.getAttribute('aria-controls')).classList.remove('open');
    });
    // Open clicked if it was closed
    if (!isOpen) {
      trigger.setAttribute('aria-expanded', 'true');
      document.getElementById(trigger.getAttribute('aria-controls')).classList.add('open');
    }
  });
});

// Package manager tabs
document.querySelectorAll('.code-tab').forEach(tab => {
  tab.addEventListener('click', () => {
    const panelId = tab.getAttribute('aria-controls');
    // Deactivate all in same tablist
    const tablist = tab.closest('[role="tablist"]');
    tablist.querySelectorAll('.code-tab').forEach(t => {
      t.classList.remove('active');
      t.setAttribute('aria-selected', 'false');
    });
    // Deactivate all panels
    tab.closest('.code-block').querySelectorAll('.code-panel').forEach(p => p.classList.remove('active'));
    // Activate
    tab.classList.add('active');
    tab.setAttribute('aria-selected', 'true');
    document.getElementById(panelId).classList.add('active');
  });
  // Keyboard nav
  tab.addEventListener('keydown', e => {
    const tabs = [...tab.closest('[role="tablist"]').querySelectorAll('.code-tab')];
    const idx = tabs.indexOf(tab);
    if (e.key === 'ArrowRight') { tabs[(idx+1)%tabs.length].click(); tabs[(idx+1)%tabs.length].focus(); }
    if (e.key === 'ArrowLeft') { tabs[(idx-1+tabs.length)%tabs.length].click(); tabs[(idx-1+tabs.length)%tabs.length].focus(); }
  });
});

// Copy to clipboard
function copyCode(btn, text) {
  navigator.clipboard.writeText(text).then(() => {
    const orig = btn.textContent;
    btn.textContent = 'Copied!';
    btn.style.color = 'var(--accent-green)';
    setTimeout(() => { btn.textContent = orig; btn.style.color = ''; }, 2000);
  });
}
</script>
